input.command:
D=<scratch>/scratchpad/analyze-tmp; mkdir -p $D && cd $D && dotnet new classlib -n Eng -o Eng >/dev/null && printf 'namespace Eng;
internal static class Money { public static decimal R(decimal x)=>x; }
' > Eng/Class1.cs && dotnet new classlib -n T -o T >/dev/null && dotnet add T reference Eng/Eng.csproj >/dev/null && printf 'namespace T;
public class C { public decimal M()=>Eng.Money.R(1m); }
' > T/Class1.cs && dotnet build T 2>&1 | grep -E 'error|Build succeeded' | head -3; cd /; rm -rf $D; ls $D 2>&1

